head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf38000";
scwin.keyStr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf38000.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const encodeParam = scwin.getTime() + "STF";
    $c.util.getComponent("ipt_gubun").setValue(scwin.encode(encodeParam));
    scwin.openDisclsHelper();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name encode
 * @description encode 처리
 * @param {*} input input
 * @returns {void}
 * @hidden N
 */
scwin.encode = function (input) {
    let output = "";
    let chr1, chr2, chr3, enc1, enc2, enc3, enc4;
    let i = 0;
    input = scwin.utf8_encode(input);
    while (i < input.length) {
        chr1 = input.charCodeAt(i++);
        chr2 = input.charCodeAt(i++);
        chr3 = input.charCodeAt(i++);
        enc1 = chr1 >> 2;
        enc2 = ((chr1 & 3) << 4) | (chr2 >> 4);
        enc3 = ((chr2 & 15) << 2) | (chr3 >> 6);
        enc4 = chr3 & 63;
        if (isNaN(chr2)) {
            enc3 = enc4 = 64;
        } else {
            if (isNaN(chr3)) {
                enc4 = 64;
            }
        }
        output = output + scwin.keyStr.charAt(enc1) + scwin.keyStr.charAt(enc2) + scwin.keyStr.charAt(enc3) + scwin.keyStr.charAt(enc4);
    }
    return output;
};

/**
 * @method
 * @name utf8_encode
 * @description utf8 encode 처리
 * @param {*} string string
 * @returns {void}
 * @hidden N
 */
scwin.utf8_encode = function (string) {
    string = string.replace(/\r\n/g, "\n");
    let utftext = "";
    for (let n = 0; n < string.length; n++) {
        const c = string.charCodeAt(n);
        if (c < 128) {
            utftext += String.fromCharCode(c);
        } else {
            if ((c > 127) && (c < 2048)) {
                utftext += String.fromCharCode((c >> 6) | 192);
                utftext += String.fromCharCode((c & 63) | 128);
            } else {
                utftext += String.fromCharCode((c >> 12) | 224);
                utftext += String.fromCharCode(((c >> 6) & 63) | 128);
                utftext += String.fromCharCode((c & 63) | 128);
            }
        }
    }
    return utftext;
};

/**
 * @method
 * @name openDisclsHelper
 * @description open Discls Helper 처리
 * @returns {void}
 * @hidden N
 */
scwin.openDisclsHelper = function () {
    const url = "http://bizguide.krx.co.kr/xmlkrx/jsp/web/XmlWebSSO.jsp?gubun=" + $c.util.getComponent("ipt_gubun").getValue();
    $c.util.getComponent('targetFrame').src = url;
};

/**
 * @method
 * @name getTime
 * @description get Time 처리
 * @returns {void}
 * @hidden N
 */
scwin.getTime = function () {
    const clientnow = new Date();
    const curYear = clientnow.getYear();
    const cYear = curYear.toString();
    const curMonth = (clientnow.getMonth()) + 1;
    let cMon = curMonth.toString();
    cMon = (cMon.length === 1) ? "0" + cMon : cMon;
    const curDay = clientnow.getDate();
    let cDa = curDay.toString();
    cDa = (cDa.length === 1) ? "0" + cDa : cDa;
    const curHours = clientnow.getHours();
    let cHour = curHours.toString();
    cHour = (cHour.length === 1) ? "0" + cHour : cHour;
    const curMinutes = clientnow.getMinutes();
    let cMin = curMinutes.toString();
    cMin = (cMin.length === 1) ? "0" + cMin : cMin;
    const curSeconds = clientnow.getSeconds();
    let cSec = curSeconds.toString();
    cSec = (cSec.length === 1) ? "0" + cSec : cSec;
    const time = cYear + cMon + cDa + cHour + cMin + cSec;
    return time;
};
